CREATE TABLE tickets(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(255),description VARCHAR(4000),owner VARCHAR(255),assignee VARCHAR(255),priority VARCHAR(255),status VARCHAR(255),created_at TIMESTAMP WITH TIME ZONE,due_at TIMESTAMP WITH TIME ZONE,resolved_at TIMESTAMP WITH TIME ZONE,version BIGINT NOT NULL DEFAULT 0);
CREATE INDEX idx_ticket_owner_status ON tickets(owner,status,id);
CREATE INDEX idx_ticket_sla ON tickets(status,due_at);
CREATE TABLE ticket_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,ticket_id BIGINT REFERENCES tickets(id),actor VARCHAR(255),action VARCHAR(255),detail VARCHAR(2000),happened_at TIMESTAMP WITH TIME ZONE);
CREATE INDEX idx_ticket_events ON ticket_events(ticket_id,id);
